import sys

# Increase recursion depth to handle deeply nested JSON structures
sys.setrecursionlimit(100000)
# Disable the integer string conversion limit to handle very large numbers
if hasattr(sys, 'set_int_max_str_digits'):
    sys.set_int_max_str_digits(0)

def parse_json(text: str) -> object:
    class JSONParser:
        def __init__(self, text):
            self.text = text
            self.pos = 0
            self.length = len(text)

        def skip_whitespace(self):
            while self.pos < self.length and self.text[self.pos] in ' \t\n\r':
                self.pos += 1

        def parse_value(self):
            self.skip_whitespace()
            if self.pos >= self.length:
                raise ValueError("Unexpected end of input")

            char = self.text[self.pos]
            if char == '{':
                return self.parse_object()
            elif char == '[':
                return self.parse_array()
            elif char == '"':
                return self.parse_string()
            elif char == '-' or '0' <= char <= '9':
                return self.parse_number()
            elif char == 't':
                return self.parse_literal('true', True)
            elif char == 'f':
                return self.parse_literal('false', False)
            elif char == 'n':
                return self.parse_literal('null', None)
            else:
                raise ValueError(f"Unexpected character {char!r}")

        def parse_literal(self, expected, value):
            if self.text.startswith(expected, self.pos):
                self.pos += len(expected)
                return value
            raise ValueError(f"Expected {expected!r}")

        def parse_string(self):
            self.pos += 1  # Skip opening quote
            res = []
            while self.pos < self.length:
                char = self.text[self.pos]
                if char == '"':
                    self.pos += 1
                    return "".join(res)
                elif char == '\\':
                    self.pos += 1
                    if self.pos >= self.length:
                        raise ValueError("Unterminated escape sequence")
                    esc = self.text[self.pos]
                    self.pos += 1
                    if esc == '"': res.append('"')
                    elif esc == '\\': res.append('\\')
                    elif esc == '/': res.append('/')
                    elif esc == 'b': res.append('\b')
                    elif esc == 'f': res.append('\f')
                    elif esc == 'n': res.append('\n')
                    elif esc == 'r': res.append('\r')
                    elif esc == 't': res.append('\t')
                    elif esc == 'u':
                        if self.pos + 4 > self.length:
                            raise ValueError("Incomplete \u escape")
                        hex_val = self.text[self.pos : self.pos + 4]
                        self.pos += 4
                        try:
                            cp = int(hex_val, 16)
                        except ValueError:
                            raise ValueError("Invalid hex in \u escape")

                        if 0xD800 <= cp <= 0xDBFF:
                            # High surrogate: must be followed by \uLow
                            if self.pos + 6 > self.length or self.text[self.pos : self.pos + 2] != '\\u':
                                raise ValueError("High surrogate not followed by low surrogate")
                            self.pos += 2
                            hex_val2 = self.text[self.pos : self.pos + 4]
                            self.pos += 4
                            try:
                                cp2 = int(hex_val2, 16)
                            except ValueError:
                                raise ValueError("Invalid hex in low surrogate escape")
                            if not (0xDC00 <= cp2 <= 0xDFFF):
                                raise ValueError("Invalid low surrogate")
                            res.append(chr(0x10000 + (cp - 0xD800) * 0x400 + (cp2 - 0xDC00)))
                        elif 0xDC00 <= cp <= 0xDFFF:
                            raise ValueError("Low surrogate without high surrogate")
                        else:
                            res.append(chr(cp))
                    else:
                        raise ValueError(f"Invalid escape sequence \\{esc}")
                elif ord(char) <= 0x1F:
                    raise ValueError("Unescaped control character")
                else:
                    res.append(char)
                    self.pos += 1
            raise ValueError("Unterminated string")

        def parse_number(self):
            start = self.pos
            if self.text[self.pos] == '-':
                self.pos += 1

            if self.pos >= self.length:
                raise ValueError("Unexpected end of number")

            if self.text[self.pos] == '0':
                self.pos += 1
                if self.pos < self.length and '0' <= self.text[self.pos] <= '9':
                    raise ValueError("Leading zero not allowed")
            elif '1' <= self.text[self.pos] <= '9':
                while self.pos < self.length and '0' <= self.text[self.pos] <= '9':
                    self.pos += 1
            else:
                raise ValueError("Invalid number format")

            has_float = False
            if self.pos < self.length and self.text[self.pos] == '.':
                has_float = True
                self.pos += 1
                if self.pos >= self.length or not ('0' <= self.text[self.pos] <= '9'):
                    raise ValueError("Fractional part must start with a digit")
                while self.pos < self.length and '0' <= self.text[self.pos] <= '9':
                    self.pos += 1

            if self.pos < self.length and self.text[self.pos] in 'eE':
                has_float = True
                self.pos += 1
                if self.pos < self.length and self.text[self.pos] in '+-':
                    self.pos += 1
                if self.pos >= self.length or not ('0' <= self.text[self.pos] <= '9'):
                    raise ValueError("Exponent must contain digits")
                while self.pos < self.length and '0' <= self.text[self.pos] <= '9':
                    self.pos += 1

            num_str = self.text[start:self.pos]
            return float(num_str) if has_float else int(num_str)

        def parse_array(self):
            self.pos += 1  # Skip [
            self.skip_whitespace()
            if self.pos < self.length and self.text[self.pos] == ']':
                self.pos += 1
                return []

            res = []
            while True:
                res.append(self.parse_value())
                self.skip_whitespace()
                if self.pos < self.length and self.text[self.pos] == ']':
                    self.pos += 1
                    return res
                if self.pos < self.length and self.text[self.pos] == ',':
                    self.pos += 1
                    self.skip_whitespace()
                    if self.pos < self.length and self.text[self.pos] == ']':
                        raise ValueError("Trailing comma in array")
                else:
                    raise ValueError("Expected , or ] in array")

        def parse_object(self):
            self.pos += 1  # Skip {
            self.skip_whitespace()
            if self.pos < self.length and self.text[self.pos] == '}':
                self.pos += 1
                return {}

            res = {}
            while True:
                self.skip_whitespace()
                if self.pos >= self.length or self.text[self.pos] != '"':
                    raise ValueError("Object key must be a string")

                key = self.parse_string()
                if key in res:
                    raise ValueError(f"Duplicate key: {key!r}")

                self.skip_whitespace()
                if self.pos >= self.length or self.text[self.pos] != ':':
                    raise ValueError("Expected : after key")
                self.pos += 1

                val = self.parse_value()
                res[key] = val

                self.skip_whitespace()
                if self.pos < self.length and self.text[self.pos] == '}':
                    self.pos += 1
                    return res
                if self.pos < self.length and self.text[self.pos] == ',':
                    self.pos += 1
                    self.skip_whitespace()
                    if self.pos < self.length and self.text[self.pos] == '}':
                        raise ValueError("Trailing comma in object")
                else:
                    raise ValueError("Expected , or } in object")

    parser = JSONParser(text)
    result = parser.parse_value()
    parser.skip_whitespace()
    if parser.pos < parser.length:
        raise ValueError("Extra data after JSON value")
    return result
